mapper.select:
/* Dashboard01Mapper.countUserSiteAuth */
SELECT
    COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* Dashboard01Mapper.selectDashLatestAcctYmd */
SELECT
    MAX(A.OCCUR_YMD)
FROM TB_ACCT A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.DEL_YN = 'N'
  AND A.USE_YN = 'Y'

/* Dashboard01Mapper.selectDashSiteBaseline */
SELECT
    S.STR_DATE                              AS strDate
  , DATE_FORMAT(S.INSERT_DATE, '%Y%m%d')    AS insertYmd
FROM TB_SITE S
WHERE S.CMPNY_CD = #{gvCmpnyCd}
  AND S.SITE_CD = #{siteCd}

/* Dashboard01Mapper.selectDashAcctGradeCounts */
SELECT
    COUNT(1)                                                                          AS monthTotalCnt
  , CAST(IFNULL(SUM(CASE WHEN A.ACCT_GRADE_CD = '100' THEN 1 ELSE 0 END), 0) AS SIGNED) AS grade100Cnt
  , CAST(IFNULL(SUM(CASE WHEN A.ACCT_GRADE_CD = '200' THEN 1 ELSE 0 END), 0) AS SIGNED) AS grade200Cnt
  , CAST(IFNULL(SUM(CASE WHEN A.ACCT_GRADE_CD = '300' THEN 1 ELSE 0 END), 0) AS SIGNED) AS grade300Cnt
FROM TB_ACCT A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.DEL_YN = 'N'
  AND A.USE_YN = 'Y'
  AND A.OCCUR_YMD BETWEEN #{fromYmd} AND #{toYmd}

/* Dashboard01Mapper.selectPatrolToday */
SELECT
    CAST(IFNULL(SUM(CASE WHEN B.CHKPT_CD IS NOT NULL THEN 1 ELSE 0 END), 0) AS SIGNED) AS todayInspectCnt
  , COUNT(1)                                                                           AS todayTotalCnt
FROM TB_CHKPT_TYPE_MGMT A
     LEFT OUTER JOIN (
        SELECT DISTINCT
            R.CMPNY_CD
          , R.SITE_CD
          , R.CHKPT_CD
        FROM TB_CHKPT_INSPECT_ANSWER R
        WHERE R.CMPNY_CD = #{gvCmpnyCd}
          AND R.SITE_CD = #{siteCd}
          AND R.WORK_DATE = #{todayYmd}
     ) B
        ON (
            A.CMPNY_CD = B.CMPNY_CD
        AND A.SITE_CD = B.SITE_CD
        AND A.CHKPT_CD = B.CHKPT_CD
        )
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* Dashboard01Mapper.selectNearMissMonthCount */
SELECT
    COUNT(1)
FROM TB_NEAR_MISS A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'
  AND A.OCCUR_DTIME >= STR_TO_DATE(CONCAT(#{fromDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')
  AND A.OCCUR_DTIME <= STR_TO_DATE(CONCAT(#{toDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')

/* Dashboard01Mapper.selectDashAttdPlanRegRate */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
)
SELECT U.NODE_CD AS nodeCd , NT.NODE_NM AS nodeNm , CAST(COUNT(1) AS SIGNED) AS totalUserCnt , CAST(IFNULL(SUM(CASE WHEN EXISTS ( SELECT 1 FROM TB_USER_WORK_PLAN WP WHERE WP.CMPNY_CD = U.CMPNY_CD AND WP.SITE_CD = U.SITE_CD AND WP.USER_CD = U.USER_CD AND WP.WORK_YMD LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%') AND WP.WORK_PLAN_CD IS NOT NULL ) THEN 1 ELSE 0 END), 0) AS SIGNED) AS regUserCnt FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.ACCOUNT_STATUS != '03' AND IFNULL(U.EMPLOYMENT_TYPE, '') != 'DAILY' GROUP BY U.NODE_CD, NT.NODE_NM ORDER BY U.NODE_CD

/* Dashboard01Mapper.selectDashAttdStatusCount */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
/* 대상 사용자 (Attd11 target_user 미러 — USE_YN='Y', 미퇴사) */ target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL ),
/* 판정 대상 계획일 (Attd11 selectAbsentDayCount 모수/제외 술어 미러 — 단 출근기록일은 유지) */ plan_day AS ( SELECT WP.CMPNY_CD , WP.SITE_CD , WP.USER_CD , WP.WORK_YMD , WP.WORK_PLAN_CD FROM target_user U INNER JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = U.CMPNY_CD AND WP.SITE_CD = U.SITE_CD AND WP.USER_CD = U.USER_CD AND WP.WORK_YMD LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%') /* 스케줄 근무일만 (WORK_PLAN_CD 가 SCH_CD — 연차셀 LEAVE_CD 분리) */ WHERE WP.WORK_PLAN_CD IS NOT NULL AND EXISTS ( SELECT 1 FROM TB_SCH_MGMT M WHERE M.CMPNY_CD = WP.CMPNY_CD AND M.SITE_CD = WP.SITE_CD AND M.SCH_CD = WP.WORK_PLAN_CD UNION ALL SELECT 1 FROM TB_SCH_MGMT_HIST H WHERE H.CMPNY_CD = WP.CMPNY_CD AND H.SITE_CD = WP.SITE_CD AND H.SCH_CD = WP.WORK_PLAN_CD ) /* 미래일 제외 (오늘 이후는 아직 출근 기회 미도래 — 오늘 포함) */ AND WP.WORK_YMD <= DATE_FORMAT(CURDATE(), '%Y%m%d') /* 연차일 제외 (TB_USER_LEAVE_USE 종일 확정 — Attd05 단일출처 술어 미러) */ AND NOT EXISTS ( SELECT 1 FROM TB_USER_LEAVE_USE L WHERE L.CMPNY_CD = WP.CMPNY_CD AND L.USER_CD = WP.USER_CD AND L.LEAVE_STATUS = 'CONFIRMED' AND L.DEL_YN = 'N' AND L.USE_UNIT_TYPE = '00' AND L.START_DATE <= WP.WORK_YMD AND L.END_DATE >= WP.WORK_YMD ) /* 휴일 제외 (HOLIDAY_TYPE 전체) */ AND NOT EXISTS ( SELECT 1 FROM TB_HOLIDAY HD WHERE HD.CMPNY_CD = WP.CMPNY_CD AND HD.USE_YN = 'Y' AND DATE_FORMAT(HD.HOLIDAY_YMD, '%Y%m%d') = WP.WORK_YMD ) ),
/* 계획일 1일 = 1상태 롤업 (차수 지각/조퇴는 MAX 로 접기) */ day_status AS ( SELECT P.USER_CD , P.WORK_YMD /* 그날 어느 차수든 출근기록(CHECK_IN) 있으면 1 — 0 이면 미출근 */ , MAX(CASE WHEN A.CHECK_IN_TIME IS NOT NULL AND A.CHECK_IN_TIME <> '' THEN 1 ELSE 0 END) AS hasCheckIn /* 지각 플래그 (Attd08 CASE 이식 — 실제 출근 일시 > 스케줄 시작 일시) */ , MAX(CASE WHEN A.WORK_SEQ = 1 AND SCH.FST_SCH_STR_TIME IS NOT NULL AND A.CHECK_IN_TIME IS NOT NULL AND A.CHECK_IN_TIME <> '' AND CONCAT(IFNULL(A.CHECK_IN_DATE, A.WORK_YMD), A.CHECK_IN_TIME) > CONCAT(A.WORK_YMD, SCH.FST_SCH_STR_TIME) THEN 1 WHEN A.WORK_SEQ = 2 AND SCH.SEC_SCH_STR_TIME IS NOT NULL AND A.CHECK_IN_TIME IS NOT NULL AND A.CHECK_IN_TIME <> '' AND CONCAT(IFNULL(A.CHECK_IN_DATE, A.WORK_YMD), A.CHECK_IN_TIME) > CONCAT(A.WORK_YMD, SCH.SEC_SCH_STR_TIME) THEN 1 ELSE 0 END) AS lateFlag /* 조퇴 플래그 (Attd08 CASE 이식 — 실제 퇴근 일시 < 스케줄 종료 일시, 야간 익일 보정) */ , MAX(CASE WHEN A.WORK_SEQ = 1 AND SCH.FST_SCH_END_TIME IS NOT NULL AND A.CHECK_OUT_TIME IS NOT NULL AND A.CHECK_OUT_TIME <> '' AND CONCAT(IFNULL(A.CHECK_OUT_DATE, A.WORK_YMD), A.CHECK_OUT_TIME) < CONCAT( CASE WHEN SCH.FST_SCH_STR_TIME IS NOT NULL AND SCH.FST_SCH_END_TIME < SCH.FST_SCH_STR_TIME THEN DATE_FORMAT(DATE_ADD(STR_TO_DATE(A.WORK_YMD, '%Y%m%d'), INTERVAL 1 DAY), '%Y%m%d') ELSE A.WORK_YMD END , SCH.FST_SCH_END_TIME) THEN 1 WHEN A.WORK_SEQ = 2 AND SCH.SEC_SCH_END_TIME IS NOT NULL AND A.CHECK_OUT_TIME IS NOT NULL AND A.CHECK_OUT_TIME <> '' AND CONCAT(IFNULL(A.CHECK_OUT_DATE, A.WORK_YMD), A.CHECK_OUT_TIME) < CONCAT( CASE WHEN SCH.SEC_SCH_STR_TIME IS NOT NULL AND SCH.SEC_SCH_END_TIME < SCH.SEC_SCH_STR_TIME THEN DATE_FORMAT(DATE_ADD(STR_TO_DATE(A.WORK_YMD, '%Y%m%d'), INTERVAL 1 DAY), '%Y%m%d') ELSE A.WORK_YMD END , SCH.SEC_SCH_END_TIME) THEN 1 ELSE 0 END) AS earlyFlag FROM plan_day P LEFT JOIN TB_USER_ATTD_MGMT A ON A.CMPNY_CD = P.CMPNY_CD AND A.SITE_CD = P.SITE_CD AND A.USER_CD = P.USER_CD AND A.WORK_YMD = P.WORK_YMD AND A.WORK_SEQ IN (1, 2) AND A.DEL_YN = 'N' /* 근무일 기준 유효 스케줄 (effective-dating — Attd11 SCH 서브쿼리 복제) */ LEFT JOIN ( SELECT E.CMPNY_CD , E.SITE_CD , E.SCH_CD , E.APPLY_DATE , E.FST_SCH_STR_TIME , E.FST_SCH_END_TIME , E.SEC_SCH_STR_TIME , E.SEC_SCH_END_TIME FROM ( SELECT M.CMPNY_CD , M.SITE_CD , M.SCH_CD , M.APPLY_DATE , M.FST_SCH_STR_TIME , M.FST_SCH_END_TIME , M.SEC_SCH_STR_TIME , M.SEC_SCH_END_TIME , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M WHERE M.USE_YN = 'Y'
UNION ALL
SELECT H.CMPNY_CD , H.SITE_CD , H.SCH_CD , H.APPLY_DATE , H.FST_SCH_STR_TIME , H.FST_SCH_END_TIME , H.SEC_SCH_STR_TIME , H.SEC_SCH_END_TIME , H.HIST_IDX FROM TB_SCH_MGMT_HIST H WHERE H.USE_YN = 'Y' ) E WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 WHERE M2.USE_YN = 'Y' UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 WHERE H2.USE_YN = 'Y' ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) SCH ON SCH.CMPNY_CD = P.CMPNY_CD AND SCH.SITE_CD = P.SITE_CD AND SCH.SCH_CD = P.WORK_PLAN_CD AND SCH.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= P.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 WHERE M3.USE_YN = 'Y' UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 WHERE H3.USE_YN = 'Y' ) SE WHERE SE.CMPNY_CD = P.CMPNY_CD AND SE.SITE_CD = P.SITE_CD AND SE.SCH_CD = P.WORK_PLAN_CD ) GROUP BY P.USER_CD, P.WORK_YMD )
SELECT CAST(COUNT(1) AS SIGNED) AS targetDayCnt , CAST(IFNULL(SUM(CASE WHEN hasCheckIn = 1 AND lateFlag = 0 AND earlyFlag = 0 THEN 1 ELSE 0 END), 0) AS SIGNED) AS normalCnt , CAST(IFNULL(SUM(CASE WHEN hasCheckIn = 1 AND lateFlag = 1 THEN 1 ELSE 0 END), 0) AS SIGNED) AS lateCnt , CAST(IFNULL(SUM(CASE WHEN hasCheckIn = 1 AND lateFlag = 0 AND earlyFlag = 1 THEN 1 ELSE 0 END), 0) AS SIGNED) AS earlyLeaveCnt , CAST(IFNULL(SUM(CASE WHEN hasCheckIn = 0 THEN 1 ELSE 0 END), 0) AS SIGNED) AS absentCnt FROM day_status

/* Dashboard01Mapper.selectOvertimeMonthlyTotals */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
) SELECT SUBSTRING(O.WORK_YMD, 1, 6) AS ym /* 'YYYYMM' — service 에서 'YYYY-MM' 변환 */ , SUM(O.WORK_MINUTES) AS totalMinutes FROM TB_USER_OVERTIME_MGMT O INNER JOIN node_tree NT ON O.CMPNY_CD = NT.CMPNY_CD AND O.SITE_CD = NT.SITE_CD AND O.NODE_CD = NT.NODE_CD /* Attd_07/08과 동일: NODE_CD NULL 행 제외 */ WHERE O.CMPNY_CD = #{gvCmpnyCd} AND O.SITE_CD = #{siteCd} AND O.DEL_YN = 'N' AND O.OT_STATUS <> 'CANCELLED' /* Attd_07/08과 동일 술어 */ AND O.WORK_YMD >= #{fromYmd} AND O.WORK_YMD <= #{toYmd} GROUP BY SUBSTRING(O.WORK_YMD, 1, 6)

/* Dashboard01Mapper.selectLeaveGrantTotal */
WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
SELECT IFNULL(SUM(G.GRANT_DAYS), 0) AS grantDays FROM TB_USER U JOIN TB_USER_LEAVE_GRANT G ON G.CMPNY_CD = U.CMPNY_CD AND G.USER_CD = U.USER_CD AND G.DEL_YN = 'N' AND G.STATUS IN ('ACTIVE', 'EXHAUSTED') /* User01Mapper L879와 동일. AVAIL 술어 미적용(§0-17) */ AND G.GRANT_TYPE LIKE 'STATUTORY\_%' WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL AND U.ACCOUNT_STATUS IN ('01', '04') /* Attd_09 직원 모집단과 동일 */ AND U.SITE_CD = #{siteCd}
AND EXISTS ( SELECT 1 FROM node_tree NT WHERE NT.CMPNY_CD = U.CMPNY_CD AND NT.SITE_CD = U.SITE_CD AND NT.NODE_CD = U.NODE_CD )
AND U.NODE_CD = #{nodeCd}

/* Dashboard01Mapper.selectLeaveUseSplit */
WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
SELECT IFNULL(SUM(CASE WHEN LU.START_DATE <= DATE_FORMAT(NOW(), '%Y%m%d') THEN LU.LEAVE_DAYS ELSE 0 END), 0) AS usedDays , IFNULL(SUM(CASE WHEN LU.START_DATE > DATE_FORMAT(NOW(), '%Y%m%d') THEN LU.LEAVE_DAYS ELSE 0 END), 0) AS plannedDays FROM TB_USER U JOIN TB_USER_LEAVE_USE LU ON LU.CMPNY_CD = U.CMPNY_CD AND LU.USER_CD = U.USER_CD AND LU.LEAVE_STATUS = 'CONFIRMED' /* 취소분(CANCELLED) 제외 */ AND LU.DEL_YN = 'N' JOIN TB_USER_LEAVE_GRANT G ON G.CMPNY_CD = LU.CMPNY_CD AND G.GRANT_ID = LU.GRANT_ID /* 법정 판별 = GRANT_ID 경유(§0-16) */ AND G.DEL_YN = 'N' AND G.STATUS IN ('ACTIVE', 'EXHAUSTED') /* 부여 분모 쿼리와 자구 동일 */ AND G.GRANT_TYPE LIKE 'STATUTORY\_%' WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL AND U.ACCOUNT_STATUS IN ('01', '04') AND U.SITE_CD = #{siteCd}
AND EXISTS ( SELECT 1 FROM node_tree NT WHERE NT.CMPNY_CD = U.CMPNY_CD AND NT.SITE_CD = U.SITE_CD AND NT.NODE_CD = U.NODE_CD )
AND U.NODE_CD = #{nodeCd}
